import fs from 'node:fs'

const P='invisible-man', worldId=`${P}-world`, now=1787529600000, base={worldId,createdAt:now,updatedAt:now}
const id=(k,s)=>`${P}-${k}-${s}`, I=s=>id('image',s), C=s=>id('character',s), L=s=>id('location',s), M=s=>id('map',s), Ch=n=>id('chapter',String(n).padStart(2,'0')), EV=s=>id('event',s), Item=s=>id('item',s), T=s=>id('thread',s), O=s=>id('motif',s), F=s=>id('faction',s), K=s=>id('fact',s), R=s=>id('relationship',s)
const commons=(name,width=1600)=>`https://commons.wikimedia.org/wiki/Special:Redirect/file/${encodeURIComponent(name)}?width=${width}`
// W23-7: assets are named by the path this app serves them from, resolved at
// read time against `import.meta.env.BASE_URL` (see `blobEntryUrl`). They used
// to be absolute `raw.githubusercontent.com` URLs, which made three books
// depend on a branch of a public repository for artwork that is already in
// `dist/` — and made them fail offline, under a banner saying the picture was
// "kept on the web rather than in the book" when it was in the book all along.
const repo='library/the-invisible-man'
const image=(s,url,mimeType='image/jpeg')=>({...base,id:I(s),mimeType,url})
const repoImage=(group,s)=>image(`${group}-${s}`,`${repo}/art/${group}/${s}.jpg`,'image/jpeg')

const mapInfo={
 england:{url:commons('Map of England and Wales.jpg',1600),width:1600,height:1934},
 iping:{url:`${repo}/maps/iping.svg`,width:1600,height:1000},
 coach:{url:`${repo}/maps/coach-and-horses.svg`,width:1400,height:900},
 london:{url:commons("1890 Bacon Traveler's Pocket Map of London, England - Geographicus - London-bacon-1890.jpg",1800),width:1800,height:1379},
 burdock:{url:`${repo}/maps/port-burdock.svg`,width:1600,height:1000},
 kemp:{url:`${repo}/maps/kemp-house.svg`,width:1400,height:900},
}
const blobs=[image('cover',commons('Wells - The Invisible Man - Pearson cover 1897.jpg',900)),...Object.entries(mapInfo).map(([s,v])=>image(`map-${s}`,v.url,v.url.endsWith('.svg')?'image/svg+xml':'image/jpeg'))]
const maps=[
 ['england',null,'England and Wales, 1897','A period national map locating London and the fictionalised southern-English towns of Griffin’s flight.'],
 ['iping','england','Iping and the Rother Valley','An original editorial village plan separating the inn, vicarage, surgery, shops, and roads used during Griffin’s stay.'],
 ['coach','iping','The Coach and Horses','An original interpretive ground plan of the inn’s public rooms, yard, and Griffin’s quarters.'],
 ['london','england','Victorian London','Bacon’s 1890 street map for Griffin’s experiments and his attempt to assemble a visible disguise.'],
 ['burdock','england','Port Burdock','An original editorial plan of the fictional coastal town where Marvel seeks protection and Kemp lives above the sea.'],
 ['kemp','burdock','Dr Kemp’s House','An original interpretive plan joining the rooms used during Griffin’s confession and the final siege.'],
].map(([s,p,name,description])=>({...base,id:M(s),parentMapId:p?M(p):null,name,description,imageId:I(`map-${s}`),imageWidth:mapInfo[s].width,imageHeight:mapInfo[s].height,scalePixelsPerUnit:null,scaleUnit:null,levelGroupId:null,levelIndex:0,levelLabel:''}))

