const chapterRows=[
 ['The Strange Man’s Arrival','A bandaged stranger walks from Bramblehurst through snow and takes a private room at the Coach and Horses.'],
 ['Mr Teddy Henfrey’s First Impressions','A clock repair gives Henfrey time to inspect the stranger and circulate suspicion.'],
 ['The Thousand and One Bottles','Griffin’s luggage arrives; a dog bite and his crowded chemical work deepen the mystery.'],
 ['Mr Cuss Interviews the Stranger','Professional curiosity brings Cuss face to face with an apparently empty sleeve.'],
 ['The Burglary at the Vicarage','Money vanishes from the Buntings’ study although no burglar can be seen.'],
 ['The Furniture That Went Mad','The Halls find Griffin absent while clothes and furniture move with violent purpose.'],
 ['The Unveiling of the Stranger','Confronted over bills and burglary, Griffin removes the disguise and resists arrest.'],
 ['In Transit','An unseen traveller crosses the countryside, briefly betrayed by sound.'],
 ['Mr Thomas Marvel','Griffin recruits a tramp through demonstrations, threats, and promises.'],
 ['Mr Marvel’s Visit to Iping','Marvel enters the disrupted inn to recover Griffin’s books and possessions.'],
 ['In the Coach and Horses','Cuss and Bunting inspect the notebooks while Griffin returns unseen to reclaim them.'],
 ['The Invisible Man Loses His Temper','The village’s resistance provokes a violent escape from Iping.'],
 ['Mr Marvel Discusses His Resignation','Marvel attempts to leave Griffin’s service and learns how little freedom the arrangement allows.'],
 ['At Port Stowe','Newspaper reports transform the local mystery into a regional hunt while Marvel tries to conceal his burden.'],
 ['The Man Who Was Running','Marvel’s desperate run announces the invisible pursuit before he reaches anyone able to help.'],
 ['In the Jolly Cricketers','Marvel finds a barricaded refuge and Griffin is wounded during the attempt to reach him.'],
 ['Dr Kemp’s Visitor','Kemp follows the alarm from his window and discovers a bleeding invisible man in his house.'],
 ['The Invisible Man Sleeps','Griffin sleeps while Kemp reads the evidence and quietly contacts Colonel Adye.'],
 ['Certain First Principles','Griffin explains the optics and physiology that made invisibility possible.'],
 ['At the House in Great Portland Street','Griffin recalls the cat experiment, his theft from his father, and his own transformation.'],
 ['In Oxford Street','Newly invisible, Griffin discovers that cold, crowds, dirt, and traffic make freedom nearly unlivable.'],
 ['In the Emporium','A department store provides a night’s refuge, but dawn forces Griffin to abandon food and clothes.'],
 ['In Drury Lane','A costume shop yields the disguise that lets Griffin rent rooms and travel among the visible.'],
 ['The Plan That Failed','Griffin proposes a reign of terror, discovers Kemp’s betrayal, and escapes the police cordon.'],
 ['The Hunting of the Invisible Man','Kemp and Adye organize roads, food, dogs, and public vigilance against an enemy no one can see.'],
 ['The Wicksteed Murder','Evidence in a field reveals the deadly change in Griffin’s campaign.'],
 ['The Siege of Kemp’s House','Griffin attacks Kemp’s home, shoots Adye, breaks through doors, and drives Kemp into flight.'],
 ['The Hunter Hunted','A public chase reverses the hunt; Griffin is seized, killed, and gradually becomes visible.'],
 ['Epilogue','Marvel prospers as an innkeeper while privately guarding the notebooks he cannot decipher.'],
]
const timelineId=id('timeline','main')
const chapters=chapterRows.map(([title,summary],i)=>({...base,id:Ch(i+1),timelineId,number:i+1,title,summary,status:'final',targetWordCount:null}))

const beats=[
 [1,'arrival','A Stranger in the Snow','Griffin walks from Bramblehurst and purchases privacy, fire, and a room at the inn.','parlour',{griffin:'Cold and exhausted, he secures shelter while keeping every feature covered.', 'mrs-hall':'Welcomes an unusually free-spending winter guest and suppresses her questions.'},3,40],
 [1,'meal','The Covered Meal','Mrs Hall sees the stranger eat behind a cloth while his goggles, bandages, and false features remain in place.','parlour',{griffin:'Eats only after arranging the room to hide the absence beneath his disguise.','mrs-hall':'Moves from hospitality to unease when ordinary explanations no longer fit what she observes.'},2,40.3],
 [2,'clock','Henfrey Prolongs the Repair','Teddy Henfrey works slowly at the parlour clock to study the guest.','parlour',{griffin:'Endures the intrusion until suspicion hardens into an order to finish and leave.',henfrey:'Turns a small repair into deliberate surveillance and leaves eager to share his impressions.','mrs-hall':'Admits Henfrey because the clock offers a respectable reason to inspect her difficult lodger.'},3,41],
 [3,'luggage','The Bottles Arrive','Fearenside delivers boxes of bottles while his dog attacks the stranger in the yard.','yard',{griffin:'Retreats at once after the dog tears his glove and trouser leg.',fearenside:'Controls the dog, then interprets the dark gap he glimpsed through his own assumptions.', 'george-hall':'Follows to offer help and sees a sleeve and clothing that do not reveal an ordinary wound.'},4,82],
 [3,'laboratory','A Room Full of Glass','Griffin unpacks bottles and begins sustained chemical work behind a locked door.','griffin-room',{griffin:'Works furiously toward visibility while frustration and broken glass make the room unsafe.', 'mrs-hall':'Balances payment against stains, noise, and the mounting disorder in her best room.'},3,82.4],
 [4,'cuss-interview','The Empty Sleeve','Cuss questions Griffin and encounters movement inside a sleeve that contains no visible arm.','griffin-room',{griffin:'Punishes Cuss’s prying with a controlled demonstration that quickly becomes a threat.',cuss:'Enters as a confident doctor and leaves shaken by touch with nothing he can see.'},4,100],
 [5,'vicarage-burglary','Coins in an Empty Room','The Buntings hear drawers, footsteps, and coins although the study appears empty.','vicarage',{bunting:'Searches his study in growing disbelief as his household money disappears.', 'mrs-bunting':'Follows the sounds and confirms that the thief leaves no visible body.'},4,118],
 [6,'empty-room','The Guest Is Missing','Mrs Hall enters Griffin’s room and finds the bed empty, the clothes discarded, and the door mysteriously unlocked.','griffin-room',{'mrs-hall':'Inspects the abandoned disguise and begins to connect it with the night’s burglary.', 'george-hall':'Joins the search and recognizes that the room cannot be explained as ordinary absence.'},3,119],
 [6,'furniture','Furniture Drives Them Out','Clothes, chair, and bedclothes move as if animated and force the Halls from the room.','griffin-room',{griffin:'Uses invisibility and household objects to terrify the intruders out of his workspace.','mrs-hall':'Retreats from a room that now seems violently haunted.', 'george-hall':'Abandons practical scepticism when the furniture attacks in coordinated motion.'},5,119.1],
 [7,'unveiling','No Face at All','Pressed for rent and explanations, Griffin tears away the bandages and false face before the bar crowd.','bar',{griffin:'Reveals emptiness where a head should be and tries to convert shock into control.','mrs-hall':'Refuses further intimidation and demands payment despite the impossible sight.','cuss':'Recognizes the phenomenon that frightened him in private.',bunting:'Confronts visible proof that the village mystery is physical rather than supernatural.',wadgers:'Braces for practical action but hesitates before an opponent without a visible target.'},5,143],
 [7,'arrest','Jaffers Attempts the Arrest','Jaffers persists as Griffin strips away the rest of the visible disguise and fights free.','bar',{griffin:'Abandons concealment, removes his clothes, and uses invisibility to break the arrest.',jaffers:'Keeps hold as long as possible, treating invisibility as no exemption from a warrant.','mrs-hall':'Gets clear of the struggle while the inn becomes a public battleground.',cuss:'Tries to assist but cannot track the hands striking through the crowd.',bunting:'Joins the confused resistance and loses control of the room.'},5,143.1],
 [8,'gibbons','A Sneeze on the Road','A passer-by hears a sneeze, curse, and footsteps moving through empty country.','iping-road',{griffin:'Moves away from Iping unclothed, exposed to cold, and briefly betrayed by his breathing.'},2,143.4],
 [9,'marvel-recruited','The Voice beside Marvel','Griffin proves his presence with stones and compels Marvel to become his visible agent.','southern-downs',{griffin:'Selects an isolated man he can intimidate into carrying clothes, books, and money.',marvel:'Moves from incredulity to frightened compliance while looking for the limits of the unseen threat.'},4,143.7],
 [10,'marvel-returns','Marvel Enters Iping','Marvel slips into the village while the Whit Monday crowd retells the morning’s impossible events.','village-green',{marvel:'Attempts to look harmless while following Griffin’s instructions toward the inn.',huxter:'Watches the unfamiliar tramp and becomes alert when property begins leaving the inn.',griffin:'Directs the theft from nearby invisibility and keeps Marvel moving.'},3,144],
 [10,'books-stolen','Huxter Gives Chase','Marvel runs with the notebooks and bundle; Huxter pursues and is struck down by Griffin.','huxter-shop',{marvel:'Clutches the recovered books and runs before the village can close around him.',huxter:'Treats the departure as visible theft and charges after the carrier.',griffin:'Protects the notebooks by attacking the first pursuer.'},5,144.1],
 [11,'notebooks-opened','Cuss and Bunting Read the Cipher','The doctor and vicar examine Griffin’s notebooks in the parlour but cannot interpret the notation.','parlour',{cuss:'Searches for a scientific key to the phenomenon and finds only dense cipher.',bunting:'Applies his classical learning to symbols that refuse ordinary translation.',griffin:'Returns unseen and listens while his work is handled by others.'},3,144.05],
 [11,'books-reclaimed','The Invisible Robber Reclaims His Work','Griffin forces Cuss and Bunting to surrender clothing and information while Marvel removes the books.','parlour',{griffin:'Uses blows and humiliation to recover control of the records.',cuss:'Complies when unseen hands turn intellectual curiosity into immediate danger.',bunting:'Surrenders the notebooks rather than risk further violence.',marvel:'Carries the recovered work out through the public confusion.'},5,144.12],
 [12,'iping-rout','The Village Is Scattered','Griffin lashes out through the green, striking pursuers and clearing a path away from Iping.','village-green',{griffin:'Converts frustration into indiscriminate force and abandons any remaining claim to harmless secrecy.',wadgers:'Tries to rally resistance before unseen blows scatter the practical men of the village.',huxter:'Recovers into a crowd that can neither see nor corner its attacker.',jaffers:'Lies incapacitated after the failed arrest while the fugitive escapes.'},5,144.2],
 [13,'resignation','Marvel Tries to Resign','On the road Marvel pleads to be released and is threatened back into service.','southern-downs',{marvel:'Tests argument and self-deprecation as routes to freedom, then continues under fear.',griffin:'Refuses to lose the only visible carrier available to him.'},3,144.8],
 [14,'newspaper','The Mariner Reads the News','At Port Stowe a mariner reads the Iping report aloud while Marvel pretends ignorance.','port-stowe',{marvel:'Tries to conceal that the advertised fugitive is beside him and that the books are under his coat.',mariner:'Enjoys the extraordinary report until interruptions make Marvel’s discomfort suspicious.',griffin:'Listens invisibly and cuts off a conversation that threatens his control.'},3,145.2],
 [14,'books-seized','The Books Change Hands','Griffin attacks and takes the books back when Marvel’s concealment and conversation fail.','port-stowe',{griffin:'Reasserts possession of the scientific record through force.',marvel:'Loses the burden briefly but gains certainty that escape must reach armed witnesses.',mariner:'Retreats from blows that arrive without a visible assailant.'},4,145.3],
 [15,'marvel-runs','A Man Running Hard','Marvel races into Port Burdock crying that the Invisible Man is behind him.','burdock-street',{marvel:'Makes fear public and chooses a crowded refuge over continued obedience.',griffin:'Pursues closely, intent on recovering both servant and notebooks.'},4,145.7],
 [16,'pub-barricade','Barricade at the Jolly Cricketers','The barman and patrons lock the doors and prepare weapons while Marvel hides inside.','jolly-cricketers',{marvel:'Begins to believe visible strangers may protect him if they accept the threat quickly enough.',barman:'Turns a public house into a defensible room and assigns men to doors and windows.',griffin:'Tests entrances and windows for a route to the man who escaped him.'},4,145.75],
 [16,'griffin-shot','A Shot through the Dark','Griffin breaks a window to reach Marvel and is wounded by a revolver shot.','jolly-cricketers',{griffin:'Withdraws bleeding after the first organized armed resistance he has faced.',marvel:'Remains inside the barricade, alive and still in possession of the notebooks.',barman:'Keeps the room closed after the shot, unsure whether the unseen attacker has truly gone.'},5,145.8],
 [17,'kemp-window','Kemp Watches the Pursuit','From his hilltop study Kemp sees Marvel running and dismisses talk of invisibility as panic.','study',{kemp:'Observes the chase as a medical man interested in collective excitement rather than magic.',marvel:'Appears below as the visible centre of a danger Kemp does not yet understand.'},2,145.7],
 [17,'griffin-arrives','Blood on the Landing','Kemp finds drops of blood and then recognizes Griffin’s voice and injured invisible body.','stair-hall',{griffin:'Reaches a former acquaintance wounded, exhausted, and demanding secrecy.',kemp:'Moves from scepticism to clinical attention when blood and touch confirm the visitor.'},4,146],
 [18,'griffin-sleeps','A Locked Door','After food and treatment Griffin sleeps while Kemp locks the room from outside.','bedroom',{griffin:'Sleeps after securing a promise of temporary shelter.',kemp:'Contains the immediate risk and begins evaluating the guest through evidence rather than loyalty.'},3,146.2],
 [18,'kemp-warns-adye','Kemp Sends a Warning','Kemp compares Griffin’s story with newspapers and sends a message to Colonel Adye.','study',{kemp:'Concludes that the invisible scientist is dangerous enough to require coordinated arrest.',adye:'Receives the first credible scientific warning and begins moving police toward the house.'},4,146.3],
 [19,'principles','The Refractive Argument','Griffin explains how tissue can become optically continuous with air.','dining-room',{griffin:'Presents the theory with pride, expecting scientific comprehension to justify what followed.',kemp:'Follows the optics while separating intellectual achievement from moral permission.'},3,146.5],
 [20,'cat-experiment','The Cat Becomes Invisible','Griffin recalls making a cat transparent in his Great Portland Street room.','great-portland',{griffin:'Confirms the method on a living animal but cannot wholly erase the eyes and claws.'},4,-48,true],
 [20,'father-money','The Cost of the Experiment','Griffin steals money from his father; the loss contributes to his father’s death.','great-portland',{griffin:'Treats family trust as expendable funding and suppresses grief beneath urgency.',father:'Faces disgrace and despair after the money he entrusted is gone.'},5,-41,true],
 [20,'self-experiment','Griffin Erases Himself','Griffin subjects his own body to the process and destroys the room before discovery.','great-portland',{griffin:'Endures pain and irreversible change, then burns evidence and leaves visible life behind.'},5,-35,true],
 [21,'oxford-crowd','Invisible in Oxford Street','Traffic, crowds, dirt, and snow expose the physical limits of unseen movement.','oxford-street',{griffin:'Moves naked through winter streets, injured by collisions and unable to keep mud or snow from revealing him.'},4,-34,true],
 [21,'cab-shelter','Borrowed Warmth','Griffin reaches a cabmen’s shelter but cannot remain fed, warm, and unnoticed.','cab-shelter',{griffin:'Learns that invisibility removes social access to the ordinary protections a body needs.'},3,-34.4,true],
 [22,'emporium-night','Night in the Emporium','Griffin eats, sleeps, and dresses inside the closed department store.','omnium',{griffin:'Builds a temporary visible self from shop goods and briefly recovers comfort.'},3,-33,true],
 [22,'emporium-morning','Staff Discover the Intruder','Morning workers corner the dressed intruder, forcing Griffin to strip and escape unseen.','omnium',{griffin:'Abandons warmth and property to regain the tactical advantage of invisibility.'},5,-32.7,true],
 [23,'costume-shop','A Visible Outline','Griffin overpowers the costumier and assembles the bandaged disguise later seen at Iping.','drury-lane',{griffin:'Uses violence to obtain the face, clothing, and money needed to re-enter public space.'},5,-32,true],
 [24,'terror-plan','The First Year of the Invisible Man','Griffin asks Kemp to become a partner in systematic terror and controlled killing.','dining-room',{griffin:'Frames fear and murder as rational instruments for ruling visible society.',kemp:'Keeps him talking while rejecting the plan and listening for the approaching police.'},5,146.7],
 [24,'police-arrive','The Trap Closes','Adye’s men arrive; Griffin discovers Kemp’s betrayal and escapes through the house.','stair-hall',{griffin:'Turns on Kemp and forces a path out before the police can close every exit.',kemp:'Survives the immediate attack and commits fully to stopping his former acquaintance.',adye:'Positions officers around the house but cannot contain an opponent who sees the cordon.'},5,146.8],
 [25,'manhunt','No Food and No Open Road','Kemp and Adye organize a public search using locked food, blocked roads, dogs, and widespread warning.','burdock-police',{kemp:'Designs restrictions around Griffin’s bodily needs rather than around visibility.',adye:'Converts the strategy into police orders and civilian alerts.'},4,147],
 [26,'wicksteed','The Iron Rod in the Field','Searchers find Wicksteed dead near the rod he appears to have followed.','wicksteed-field',{wicksteed:'Pursues the moving iron in alarm and is killed before he can bring help.',griffin:'Escalates from threatened terror to an act the search party reads as deliberate murder.'},5,147.3],
 [27,'adye-shot','Adye at the Garden Gate','Griffin confronts Adye outside Kemp’s house, takes the revolver, and shoots him as he resists.','garden',{griffin:'Demands entry information and fires when Adye refuses passive surrender.',adye:'Attempts to disarm the unseen attacker and falls wounded while protecting the siege plan.'},5,148],
 [27,'doors-broken','The House under the Axe','Griffin smashes doors and windows while Kemp and servants defend the stair.','stair-hall',{griffin:'Uses the axe and unseen movement to penetrate the fortified house.',kemp:'Falls back through prepared doors while searching for a route into the town crowd.'},5,148.1],
 [27,'kemp-flight','Kemp Runs for the Town','Kemp escapes through the garden and races downhill with Griffin close behind.','kemp-hill',{kemp:'Chooses populated streets where witnesses and many hands may reverse the advantage.',griffin:'Follows openly through dust and impact, determined to kill the man who betrayed him.'},5,148.2],
 [28,'public-chase','The Crowd Turns','Workers and townspeople join Kemp, tracking Griffin by blows, footprints, dust, and grasped limbs.','burdock-street',{kemp:'Survives by keeping the pursuit visible to a crowd willing to close around empty space.',griffin:'Loses mobility as many attackers respond to contact rather than sight.',barman:'Recognizes the same unseen danger from the pub attack and helps direct resistance.'},5,148.25],
 [28,'griffin-death','A Body Returns','Griffin dies in the road and the outline of his body slowly becomes visible.','burdock-street',{griffin:'Dies restrained by the crowd as transparency recedes from the damaged body.',kemp:'Stops further blows and watches the scientific impossibility become a dead young man.'},5,148.3],
 [29,'marvel-inn','The Books in the Cupboard','Years later Marvel runs an inn, tells the story, and studies the notebooks in secret.','burdock-police',{marvel:'Guards the ciphered books and dreams of discovering the power Griffin could not safely use.'},2,878],
]
